import { useState } from 'react';
import client from '../../api/client';

const formatCOP = (v) =>
  new Intl.NumberFormat('es-CO', { style:'currency', currency:'COP', minimumFractionDigits:0 }).format(v||0);

export default function Reportes() {
  const [desde, setDesde]   = useState('');
  const [hasta, setHasta]   = useState('');
  const [data, setData]     = useState(null);
  const [loading, setLoading] = useState(false);

  //const today = new Date().toISOString().split('T')[0];
  const today = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Bogota' });

  const cargar = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (desde) params.append('desde', desde);
      if (hasta) params.append('hasta', hasta);
      const { data: res } = await client.get(`/api/ventas/reporte?${params}`);
      setData(res);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  const hoy = () => { setDesde(today); setHasta(today); };

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">📊 Reportes</h1>
      </div>

      <div className="card" style={{ marginBottom:16, display:'flex', gap:10, flexWrap:'wrap', alignItems:'flex-end' }}>
        <div className="field" style={{ flex:'none' }}>
          <label>Desde</label>
          <input type="date" value={desde} onChange={e => setDesde(e.target.value)} />
        </div>
        <div className="field" style={{ flex:'none' }}>
          <label>Hasta</label>
          <input type="date" value={hasta} onChange={e => setHasta(e.target.value)} />
        </div>
        <button className="btn btn-secondary" onClick={hoy}>Hoy</button>
        <button className="btn btn-primary" onClick={cargar} disabled={loading}>
          {loading ? 'Cargando...' : '🔍 Generar reporte'}
        </button>
      </div>

      {data && (
        <>
          {/* Resumen */}
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(180px, 1fr))', gap:16, marginBottom:20 }}>
            {[
              { label:'Total ventas', value: data.totalVentas, isMoney: false },
              { label:'Ingresos totales', value: data.totalGeneral, isMoney: true },
              { label:'Ticket promedio', value: data.totalVentas > 0 ? data.totalGeneral / data.totalVentas : 0, isMoney: true },
            ].map(item => (
              <div key={item.label} className="card" style={{ textAlign:'center' }}>
                <p style={{ color:'#888', fontSize:'.78rem', textTransform:'uppercase', letterSpacing:'.06em', marginBottom:8 }}>{item.label}</p>
                <p style={{ fontSize:'1.5rem', fontWeight:800, color:'#1a1a2e' }}>
                  {item.isMoney ? formatCOP(item.value) : item.value}
                </p>
              </div>
            ))}
          </div>

          {/* Productos más vendidos */}
          <div className="card">
            <h3 style={{ marginBottom:14, fontSize:'1rem', fontWeight:700 }}>🏆 Productos más vendidos</h3>
            <table>
              <thead><tr><th>#</th><th>Producto</th><th>Unidades vendidas</th><th>Total generado</th></tr></thead>
              <tbody>
                {data.productosMasVendidos.map((p, i) => (
                  <tr key={p.productoId}>
                    <td><strong>{i + 1}</strong></td>
                    <td>{p.nombre}</td>
                    <td>{p.cantidad}</td>
                    <td><strong>{formatCOP(p.total)}</strong></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {!data && !loading && (
        <div className="card" style={{ textAlign:'center', padding:40, color:'#bbb' }}>
          <p style={{ fontSize:'2rem', marginBottom:12 }}>📊</p>
          <p>Selecciona un rango de fechas y genera el reporte</p>
        </div>
      )}
    </div>
  );
}
